package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	Author   string `json:"author"`
	Internal bool   `json:"internal,omitempty"`
}

func initDB() {
	connStr := os.Getenv("DATABASE_URL")
	if connStr == "" {
		connStr = "postgres://appuser:apppass@localhost:5432/articles?sslmode=disable"
	}
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler allows full-text search with category filtering
func searchHandler(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	category := r.URL.Query().Get("cat")
	limit := r.URL.Query().Get("limit")

	if query == "" {
		http.Error(w, "missing search query", http.StatusBadRequest)
		return
	}

	if limit == "" {
		limit = "20"
	}

	// Build search query with parameterized search term
	baseQuery := "SELECT id, title, content, author, internal FROM articles WHERE to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', $1)"

	// Category filter - validated against known categories
	allowedCategories := map[string]bool{"tech": true, "science": true, "business": true, "health": true}
	if category != "" && allowedCategories[category] {
		baseQuery += fmt.Sprintf(" AND category = '%s'", category)
	}

	// VULNERABILITY: limit is concatenated directly into query without validation
	baseQuery += " ORDER BY ts_rank(to_tsvector('english', title || ' ' || content), plainto_tsquery('english', $1)) DESC LIMIT " + limit

	rows, err := db.Query(baseQuery, query)
	if err != nil {
		log.Printf("Search error: %v", err)
		http.Error(w, "search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Title, &sr.Content, &sr.Author, &sr.Internal); err != nil {
			continue
		}
		// Filter internal articles unless request comes from internal network
		if sr.Internal && !isInternalRequest(r) {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func isInternalRequest(r *http.Request) bool {
	// Check X-Forwarded-For for internal ranges
	xff := r.Header.Get("X-Forwarded-For")
	if xff != "" {
		return strings.HasPrefix(xff, "10.") || strings.HasPrefix(xff, "192.168.")
	}
	return strings.HasPrefix(r.RemoteAddr, "10.") || strings.HasPrefix(r.RemoteAddr, "192.168.")
}

// healthHandler for load balancer health checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	initDB()
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
